// Einstellung: nach wie vielen Tagen nachgefasst wird.
const TAGE_BIS_ZUM_NACHFASSEN = 7;
const MS_PRO_TAG = 24 * 60 * 60 * 1000;
const heute = new Date();

// Versteht 14.10.2026 und 2026-10-14.
const leseDatum = (wert) => {
  if (!wert) return null;
  const text = String(wert).trim();
  const deutsch = text.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (deutsch) return new Date(Number(deutsch[3]), Number(deutsch[2]) - 1, Number(deutsch[1]));
  const datum = new Date(text);
  return Number.isNaN(datum.getTime()) ? null : datum;
};

return $input.all().filter((item) => {
  const zeile = item.json;
  const status = String(zeile.Status || '').trim().toLowerCase();
  const nachgefasst = String(zeile.Nachgefasst || '').trim();
  const datum = leseDatum(zeile.Angebotsdatum);
  if (status !== 'offen' || nachgefasst !== '' || !datum || !zeile['E-Mail']) return false;
  return (heute - datum) / MS_PRO_TAG >= TAGE_BIS_ZUM_NACHFASSEN;
});
